<?php
declare(strict_types=1);
function cat_projection(array $v):array{$d=$v['data'];return ['id'=>(int)$v['service_id'],'version_id'=>(int)$v['id'],'revision'=>(int)$v['revision_number'],'checksum'=>$v['checksum'],'name'=>$d['name'],'description'=>$d['description'],'category'=>$d['category'],'scope'=>$d['scope'],'deliverables'=>$d['deliverables'],'pricing_type'=>$d['pricing_type'],'packages'=>array_map(fn($p)=>array_intersect_key($p,array_flip(['id','name','description','price'])),$d['packages']),'consultation_url'=>$d['consultation_url']];}
function cat_public_list():array{
 cat_gate();$page=cc_page();$rows=crm_query("SELECT v.id FROM nd_catalog_services s JOIN nd_catalog_service_versions v ON v.service_id=s.id AND v.revision_number=s.published_revision JOIN nd_catalog_template_versions tv ON tv.id=v.template_version_id JOIN nd_catalog_templates t ON t.id=tv.template_id WHERE s.state='PUBLISHED' AND t.state='PUBLISHED' AND tv.published_at IS NOT NULL ORDER BY s.id DESC LIMIT 20 OFFSET ".(($page-1)*20))->fetchAll();return ['ok'=>true,'items'=>array_map(fn($r)=>cat_projection(cat_version('service',(int)$r['id'])),$rows),'page'=>$page,'page_size'=>20,'categories'=>cat_categories(),'requests_enabled'=>cat_requests_open()];
}
function cat_public_detail(int $id):array{cat_gate();$s=cat_record('service',$id);$vid=crm_query('SELECT id FROM nd_catalog_service_versions WHERE service_id=? AND revision_number=?',[$id,$s['published_revision']])->fetchColumn();if(!$vid)crm_fail(404,'Услуга не опубликована.');$live=cat_live((int)$vid);return ['ok'=>true,'record'=>cat_projection($live['version']),'questionnaire'=>$live['template']['data'],'template_checksum'=>$live['template']['checksum'],'requests_enabled'=>cat_requests_open()];}
function cat_list_requests(array $a):array{$page=cc_page();$where=$a['type']==='customer'?' WHERE customer_id=?':'';$rows=crm_query('SELECT id,customer_id,project_id,lead_id,deal_id,order_id,state,version,created_at FROM nd_catalog_requests'.$where.' ORDER BY id DESC LIMIT 20 OFFSET '.(($page-1)*20),$a['type']==='customer'?[$a['customer_id']]:[])->fetchAll();return ['ok'=>true,'items'=>$rows,'page'=>$page,'page_size'=>20];}
function cat_detail(array $a,int $id):array{
 $r=cat_request($a,$id);$v=cat_version('service',(int)$r['service_version_id']);$template=cat_version('template',(int)$v['template_version_id']);$record=array_intersect_key($r,array_flip(['id','project_id','lead_id','deal_id','order_id','state','version','head_revision','package_key','answers_json','file_ids_json','policy_version','created_at']));$record['service']=cat_projection($v);$record['questionnaire']=$template['data'];$record['briefs']=crm_query('SELECT id,revision_number,structured_json,checksum,policy_version,created_at FROM nd_catalog_briefs WHERE request_id=? ORDER BY revision_number DESC LIMIT 20',[$id])->fetchAll();
 $offers=crm_query('SELECT * FROM nd_catalog_offers WHERE request_id=?'.($a['type']==='customer'?' AND published_at IS NOT NULL':'').' ORDER BY id DESC LIMIT 20',[$id])->fetchAll();$record['offers']=array_map(fn($o)=>array_intersect_key($o,array_flip(['id','state','body','checksum','version','expires_at','accepted_at','published_at'])),$offers);
 if($r['state']==='AWAITING_ACCEPTANCE'&&$offers&&$offers[0]['expires_at']<=gmdate('Y-m-d H:i:s'))$record['display_state']='EXPIRED';else $record['display_state']=$r['state'];
 if($a['type']==='owner'){$q=crm_query('SELECT id,state FROM nd_quotations WHERE project_id=? ORDER BY revision_number DESC LIMIT 1',[$r['project_id']])->fetch();$record['quotation']=$q?:null;}
 return ['ok'=>true,'record'=>$record];
}
function cat_revise(array $a,int $id,array $d):array{
 return crm_idempotent('catalog:revise:'.$a['type'].':'.$a['id'].':'.$id,$d,function()use($a,$id,$d){$r=cat_request($a,$id,true);crm_version($d,$r);if(($d['confirm']??false)!==true||!in_array($r['state'],['SUBMITTED','PRICING','AWAITING_ACCEPTANCE','ACCEPTED'],true))crm_fail(409,'Новая редакция недоступна.');if((int)$r['head_revision']>=20)crm_fail(409,'Достигнут предел редакций брифа. Создайте новую заявку.');cc_project($a,(int)$r['project_id'],true,true);cat_live((int)$r['service_version_id']);$ids=crm_query('SELECT spec_revision_id FROM nd_catalog_briefs WHERE request_id=? UNION ALL SELECT proposal_revision_id FROM nd_catalog_offers WHERE request_id=?',[$id,$id])->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $rid)crm_query("UPDATE nd_cc_approvals SET status='withdrawn',version=version+1 WHERE revision_id=? AND status='pending'",[$rid]);crm_query("UPDATE nd_catalog_offers SET state='SUPERSEDED',version=version+1 WHERE request_id=? AND state IN ('DRAFT','AWAITING_ACCEPTANCE','ACCEPTED')",[$id]);crm_query("UPDATE nd_catalog_requests SET state='DRAFT',version=version+1 WHERE id=?",[$id]);cat_event($a,$r,'revision_requested');return ['ok'=>true,'id'=>$id];});
}
function cat_cancel(array $a,int $id,array $d):array{
 return crm_idempotent('catalog:cancel:'.$a['type'].':'.$a['id'].':'.$id,$d,function()use($a,$id,$d){$r=cat_request($a,$id,true);if($r['state']==='CANCELLED')return ['ok'=>true,'id'=>$id];crm_version($d,$r);if(($d['confirm']??false)!==true||$r['order_id'])crm_fail(409,'Подтверждённый заказ меняется через владельца и существующий процесс CRM.');$p=cc_project($a,(int)$r['project_id'],true,true);if($r['deal_id']){$deal=crm_record('deals',(int)$r['deal_id'],true);if(crm_query('SELECT id FROM nd_orders WHERE deal_id=? LIMIT 1',[$deal['id']])->fetchColumn())crm_fail(409,'Заказ уже создан владельцем. Согласуйте отмену через CRM.');crm_transition('deals',$deal['status'],'lost');crm_query("UPDATE nd_deals SET status='lost',loss_reason='Заявка отменена через каталог',version=version+1 WHERE id=?",[$deal['id']]);crm_event('deals',(int)$deal['id'],'updated',crm_record('deals',(int)$deal['id']),$a);}crm_transition('projects',$p['status'],'cancelled');crm_query("UPDATE nd_projects SET status='cancelled',version=version+1 WHERE id=?",[$p['id']]);crm_query("UPDATE nd_catalog_requests SET state='CANCELLED',version=version+1 WHERE id=?",[$id]);crm_query("UPDATE nd_catalog_offers SET state='CANCELLED',version=version+1 WHERE request_id=? AND state<>'SUPERSEDED'",[$id]);$ids=crm_query('SELECT spec_revision_id FROM nd_catalog_briefs WHERE request_id=? UNION ALL SELECT proposal_revision_id FROM nd_catalog_offers WHERE request_id=?',[$id,$id])->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $rid)crm_query("UPDATE nd_cc_approvals SET status='withdrawn',version=version+1 WHERE revision_id=? AND status='pending'",[$rid]);cat_event($a,$r,'cancelled');return ['ok'=>true,'id'=>$id];});
}
